 (p_body ? 'formula_outcomes' AND (jsonb_typeof(p_body->'formula_outcomes') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'formula_outcomes') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','outcome','error','diagnostic_ref'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('failed','not_requested','succeeded','unknown'))) OR (nested_record ? 'error' AND (jsonb_typeof(nested_record->'error') IS DISTINCT FROM 'string')) OR (nested_record ? 'diagnostic_ref' AND (jsonb_typeof(nested_record->'diagnostic_ref') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record->'diagnostic_ref') key WHERE key<>ALL(ARRAY['family','local_id','task_id','product_key','content_digest'])) OR NOT (nested_record->'diagnostic_ref' ? 'family') OR (nested_record->'diagnostic_ref' ? 'family' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'family') IS DISTINCT FROM 'string')) OR nested_record->'diagnostic_ref'->>'family' IS DISTINCT FROM 'native_metadata' OR NOT (nested_record->'diagnostic_ref' ? 'local_id') OR (nested_record->'diagnostic_ref' ? 'local_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'local_id') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'task_id') OR (nested_record->'diagnostic_ref' ? 'task_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'task_id') IS DISTINCT FROM 'number' OR nested_record->'diagnostic_ref'->>'task_id' !~ '^[0-9]+$')) OR (nested_record->'diagnostic_ref' ? 'task_id' AND (nested_record->'diagnostic_ref'->>'task_id')::numeric < 1) OR NOT (nested_record->'diagnostic_ref' ? 'product_key') OR (nested_record->'diagnostic_ref' ? 'product_key' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'product_key') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'content_digest') OR (nested_record->'diagnostic_ref' ? 'content_digest' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'content_digest') IS DISTINCT FROM 'string')) OR (nested_record->'diagnostic_ref' ? 'content_digest' AND nested_record->'diagnostic_ref'->>'content_digest' !~ '^[0-9a-f]{64}$')))))))) OR (p_body ? 'candidate_policy' AND (jsonb_typeof(p_body->'candidate_policy') IS DISTINCT FROM 'string' OR p_body->>'candidate_policy' NOT IN ('native-font-token-vector-ocr-word-v3','native-font-token-vector-v2','native-math-font-or-token-v1'))) OR (p_body ? 'cells_policy' AND (jsonb_typeof(p_body->'cells_policy') IS DISTINCT FROM 'string' OR p_body->>'cells_policy' NOT IN ('all-nonempty-selected-cells-v1'))) OR (p_body ? 'inline_scope' AND (jsonb_typeof(p_body->'inline_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'inline_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (p_body ? 'inline_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(p_body->'inline_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (p_body ? 'cell_scope' AND (jsonb_typeof(p_body->'cell_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'cell_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (p_body ? 'cell_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(p_body->'cell_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (p_body ? 'inline_membership' AND (jsonb_typeof(p_body->'inline_membership') IS DISTINCT FROM 'string' OR p_body->>'inline_membership' NOT IN ('descendants','direct'))) OR (p_body ? 'cell_membership' AND (jsonb_typeof(p_body->'cell_membership') IS DISTINCT FROM 'string' OR p_body->>'cell_membership' NOT IN ('descendants','direct'))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfRecordNativeHealth' USING ERRCODE='23514'; END IF;

 ELSE IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductHealth' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(p_body) key WHERE key<>ALL(ARRAY['execution_outcome','mapping_outcome','source_fidelity','validation_report'])) OR NOT (p_body ? 'execution_outcome') OR (p_body ? 'execution_outcome' AND (jsonb_typeof(p_body->'execution_outcome') IS DISTINCT FROM 'string' OR p_body->>'execution_outcome' NOT IN ('failed','partial','succeeded','unknown','unsupported'))) OR NOT (p_body ? 'mapping_outcome') OR (p_body ? 'mapping_outcome' AND (jsonb_typeof(p_body->'mapping_outcome') IS DISTINCT FROM 'string' OR p_body->>'mapping_outcome' NOT IN ('coarse','partial','unknown','unsupported'))) OR NOT (p_body ? 'source_fidelity') OR (p_body ? 'source_fidelity' AND (jsonb_typeof(p_body->'source_fidelity') IS DISTINCT FROM 'string' OR p_body->>'source_fidelity' NOT IN ('conflict','unassessed','unknown'))) OR NOT (p_body ? 'validation_report') OR (p_body ? 'validation_report' AND (jsonb_typeof(p_body->'validation_report') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductHealth' USING ERRCODE='23514'; END IF;

 END IF; END IF;
 INSERT INTO ops.pdf_stage_companion VALUES(p_build,p_build,p_family,p_local,p_body,p_ordinal) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_companion WHERE product_id=p_build AND family=p_family AND local_id=p_local AND body=p_body AND ordinal=p_ordinal) THEN
 RAISE EXCEPTION 'changed companion duplicate' USING ERRCODE='23514'; END IF;
 FOR field_ IN SELECT key,value#>>'{}' stream_id FROM jsonb_each(p_fields) LOOP
 INSERT INTO ops.pdf_stage_companion_field VALUES(p_build,p_build,p_family,p_local,field_.key,field_.stream_id,
 CASE WHEN field_.key='value' THEN 'y' ELSE 's' END) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_companion_field WHERE product_id=p_build AND family=p_family AND local_id=p_local
 AND field_name=field_.key AND stream_id=field_.stream_id) THEN RAISE EXCEPTION 'changed companion field duplicate'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM ops.pdf_stage_companion_field WHERE product_id=p_build AND family=p_family AND local_id=p_local)
 <>(SELECT count(*) FROM jsonb_object_keys(p_fields)) THEN RAISE EXCEPTION 'changed companion field inventory'; END IF;
 IF p_family='relation' THEN
 IF jsonb_typeof(p_body->'endpoints')<>'array' OR jsonb_array_length(p_body->'endpoints')=0 THEN
 RAISE EXCEPTION 'relation lacks independent endpoints' USING ERRCODE='23514'; END IF;
 FOR endpoint_ IN SELECT value FROM jsonb_array_elements(p_body->'endpoints') LOOP
 IF endpoint_ ? 'input_index' THEN
 SELECT body INTO STRICT input_ FROM ops.pdf_stage_companion WHERE product_id=p_build
 AND family='input' AND local_id=endpoint_->>'input_index';
 ELSE input_:=jsonb_build_object('task_id',0,'product_key','@self','content_digest','@self'); END IF;
 INSERT INTO ops.pdf_stage_endpoint VALUES(p_build,p_build,p_local,index_,(input_->>'task_id')::bigint,
 input_->>'product_key',input_->>'content_digest',endpoint_->>'occurrence_id',endpoint_->>'role') ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_endpoint WHERE product_id=p_build AND relation_id=p_local AND ordinal=index_
 AND occurrence_id=endpoint_->>'occurrence_id' AND role=endpoint_->>'role'
 AND target_task_id=(input_->>'task_id')::bigint AND target_content_digest=input_->>'content_digest') THEN
 RAISE EXCEPTION 'changed companion endpoint duplicate' USING ERRCODE='23514'; END IF;
 index_:=index_+1;
 END LOOP; END IF;
END

