DECLARE published ops.pdf_published_revision; origin_run bigint;
BEGIN
 PERFORM data.require_runtime_principal('read');
 IF p_project IS NULL OR p_run IS NULL OR p_release IS NULL OR p_task IS NULL
 OR p_product IS NULL OR p_digest IS NULL OR NOT EXISTS(
 SELECT FROM ops.run r WHERE r.id=p_run AND r.project_id=p_project AND r.release_id=p_release) THEN
 RAISE EXCEPTION 'published source run/project/release pin is unavailable'
 USING ERRCODE='22023'; END IF;
 PERFORM sem.require_execution_operation(p_release,'read_native_source');
 SELECT p.* INTO published FROM ops.read_pdf_published_revision(p_task,p_product,p_digest) p;
 IF NOT FOUND OR published.release_id IS DISTINCT FROM p_release THEN
 RAISE EXCEPTION 'published source pin is unavailable or staged' USING ERRCODE='22023'; END IF;
 SELECT t.run_id INTO origin_run FROM ops.task t JOIN ops.run r ON r.id=t.run_id
 WHERE t.id=p_task AND r.project_id=p_project;
 IF NOT FOUND THEN
 RAISE EXCEPTION 'published source is unavailable in this project' USING ERRCODE='22023'; END IF;
 IF origin_run<>p_run AND NOT EXISTS(WITH RECURSIVE selected_native_ancestry(task_id, product_key, content_digest) AS 
(SELECT DISTINCT kb.source_view.native_task_id AS task_id, kb.source_view.native_product_key AS product_key, kb.source_view.native_content_digest AS content_digest 
FROM kb.source_view JOIN ops.run_source_view ON ops.run_source_view.source_view_id = kb.source_view.id 
WHERE ops.run_source_view.run_id = p_run UNION SELECT ops.pdf_product_input.input_task_id AS input_task_id, ops.pdf_product_input.input_product_key AS input_product_key, ops.pdf_product_input.input_content_digest AS input_content_digest 
FROM ops.pdf_product_input JOIN selected_native_ancestry ON ops.pdf_product_input.task_id = selected_native_ancestry.task_id AND ops.pdf_product_input.product_key = selected_native_ancestry.product_key)
 SELECT selected_native_ancestry.task_id 
FROM selected_native_ancestry 
WHERE selected_native_ancestry.task_id = p_task AND selected_native_ancestry.product_key = p_product AND selected_native_ancestry.content_digest = p_digest) THEN
 RAISE EXCEPTION 'published source is outside selected run ancestry' USING ERRCODE='22023'; END IF;
 RETURN published;
END

