RETURNS TABLE(product_id TEXT,revision_id TEXT,pointer TEXT,region_index BIGINT,page_no BIGINT,page_width NUMERIC,page_height NUMERIC,"left" NUMERIC,top NUMERIC,"right" NUMERIC,bottom NUMERIC,origin TEXT) LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $read$
DECLARE published ops.pdf_published_revision;
BEGIN
 SELECT * INTO STRICT published FROM ops.read_pdf_published_revision(p_task,p_product,p_digest);
 PERFORM sem.require_execution_operation(published.release_id,'read_native_source');

IF p_pointer IS NULL THEN RAISE EXCEPTION 'published item pointer is required'
USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT * FROM ops.read_pdf_published_regions_rows(published.build_id,published.build_id,p_pointer);
END $read$

