-- Immutable section views are instances, never fabricated document/rendition rows.
CREATE OR REPLACE FUNCTION ops.publish_source_view(p_run bigint,p_task bigint,p_attempt bigint,p_holder text,p_position bigint,p_payload bytea,p_recipe bytea) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $view$
DECLARE job ops.task; run ops.run; product jsonb; parsing_item jsonb; projection jsonb; piece jsonb;
 native ops.pdf_selected_product; section ops.pdf_published_item; previous kb.source_view; result bigint;
 pos bigint:=0; stop bigint; node jsonb; spelling text; piece_pointer text; expected jsonb; coverage_universe text; local_coverage text; coverage_row ops.pdf_published_coverage;
BEGIN
 SELECT * INTO STRICT run FROM ops.run WHERE id=p_run FOR SHARE;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=p_run FOR UPDATE;
 PERFORM sem.require_execution_operation(run.release_id,'publish_source_view');
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'source view attempt lost' USING ERRCODE='P0004'; END IF;
 product:=convert_from(p_payload,'UTF8')::jsonb;
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfSourceViewPublication' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(product) key WHERE key<>ALL(ARRAY['key','document_id','native_task_id','native_product_key','native_content_digest','section_pointer','membership','projection_digest','recipe_digest','projection','replaces_source_view_id','analysis_eligible'])) OR NOT (product ? 'key') OR (product ? 'key' AND (jsonb_typeof(product->'key') IS DISTINCT FROM 'string')) OR NOT (product ? 'document_id') OR (product ? 'document_id' AND (jsonb_typeof(product->'document_id') IS DISTINCT FROM 'number' OR product->>'document_id' !~ '^[0-9]+$')) OR (product ? 'document_id' AND (product->>'document_id')::numeric < 1) OR NOT (product ? 'native_task_id') OR (product ? 'native_task_id' AND (jsonb_typeof(product->'native_task_id') IS DISTINCT FROM 'number' OR product->>'native_task_id' !~ '^[0-9]+$')) OR (product ? 'native_task_id' AND (product->>'native_task_id')::numeric < 1) OR NOT (product ? 'native_product_key') OR (product ? 'native_product_key' AND (jsonb_typeof(product->'native_product_key') IS DISTINCT FROM 'string')) OR NOT (product ? 'native_content_digest') OR (product ? 'native_content_digest' AND (jsonb_typeof(product->'native_content_digest') IS DISTINCT FROM 'string')) OR (product ? 'native_content_digest' AND product->>'native_content_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'section_pointer') OR (product ? 'section_pointer' AND (jsonb_typeof(product->'section_pointer') IS DISTINCT FROM 'string')) OR (product ? 'section_pointer' AND product->>'section_pointer' !~ '^#(/[^/]+)+$') OR NOT (product ? 'membership') OR (product ? 'membership' AND (jsonb_typeof(product->'membership') IS DISTINCT FROM 'string' OR product->>'membership' NOT IN ('descendants','direct'))) OR NOT (product ? 'projection_digest') OR (product ? 'projection_digest' AND (jsonb_typeof(product->'projection_digest') IS DISTINCT FROM 'string')) OR (product ? 'projection_digest' AND product->>'projection_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'recipe_digest') OR (product ? 'recipe_digest' AND (jsonb_typeof(product->'recipe_digest') IS DISTINCT FROM 'string')) OR (product ? 'recipe_digest' AND product->>'recipe_digest' !~ '^[0-9a-f]{64}$') OR NOT (product ? 'projection') OR (product ? 'projection' AND (jsonb_typeof(product->'projection') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'projection') key WHERE key<>ALL(ARRAY['text','pieces','items','ancestors','health'])) OR NOT (product->'projection' ? 'text') OR (product->'projection' ? 'text' AND (jsonb_typeof(product->'projection'->'text') IS DISTINCT FROM 'string')) OR (product->'projection' ? 'pieces' AND (jsonb_typeof(product->'projection'->'pieces') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'pieces') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['item_ref','start','end','kind','cell_index','source_field'])) OR (nested_record ? 'item_ref' AND (jsonb_typeof(nested_record->'item_ref') IS DISTINCT FROM 'string')) OR (nested_record ? 'item_ref' AND nested_record->>'item_ref' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'start') OR (nested_record ? 'start' AND (jsonb_typeof(nested_record->'start') IS DISTINCT FROM 'number' OR nested_record->>'start' !~ '^[0-9]+$')) OR (nested_record ? 'start' AND (nested_record->>'start')::numeric < 0) OR NOT (nested_record ? 'end') OR (nested_record ? 'end' AND (jsonb_typeof(nested_record->'end') IS DISTINCT FROM 'number' OR nested_record->>'end' !~ '^[0-9]+$')) OR (nested_record ? 'end' AND (nested_record->>'end')::numeric < 0) OR NOT (nested_record ? 'kind') OR (nested_record ? 'kind' AND (jsonb_typeof(nested_record->'kind') IS DISTINCT FROM 'string')) OR (nested_record ? 'cell_index' AND (jsonb_typeof(nested_record->'cell_index') IS DISTINCT FROM 'number' OR nested_record->>'cell_index' !~ '^[0-9]+$')) OR (nested_record ? 'cell_index' AND (nested_record->>'cell_index')::numeric < 0) OR (nested_record ? 'source_field' AND (jsonb_typeof(nested_record->'source_field') IS DISTINCT FROM 'string' OR nested_record->>'source_field' NOT IN ('cell_text','chart_cell_text','chart_title','orig','text'))))))) OR NOT (product->'projection' ? 'items') OR (product->'projection' ? 'items' AND (jsonb_typeof(product->'projection'->'items') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'items') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string') OR jsonb_array_length(product->'projection'->'items') < 1)) OR (product->'projection' ? 'items' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'items') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection' ? 'ancestors' AND (jsonb_typeof(product->'projection'->'ancestors') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'ancestors') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection' ? 'ancestors' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'ancestors') element WHERE element !~ '^#(/[^/]+)+$')) OR NOT (product->'projection' ? 'health') OR (product->'projection' ? 'health' AND (jsonb_typeof(product->'projection'->'health') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'projection'->'health') key WHERE key<>ALL(ARRAY['conversion','display_coverage','inline_coverage','cell_coverage','issues','formula_outcomes','candidate_policy','cells_policy','inline_scope','cell_scope','inline_membership','cell_membership'])) OR NOT (product->'projection'->'health' ? 'conversion') OR (product->'projection'->'health' ? 'conversion' AND (jsonb_typeof(product->'projection'->'health'->'conversion') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'conversion' NOT IN ('failure','partial_success','success'))) OR NOT (product->'projection'->'health' ? 'display_coverage') OR (product->'projection'->'health' ? 'display_coverage' AND (jsonb_typeof(product->'projection'->'health'->'display_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'display_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (product->'projection'->'health' ? 'inline_coverage') OR (product->'projection'->'health' ? 'inline_coverage' AND (jsonb_typeof(product->'projection'->'health'->'inline_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'inline_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (product->'projection'->'health' ? 'cell_coverage') OR (product->'projection'->'health' ? 'cell_coverage' AND (jsonb_typeof(product->'projection'->'health'->'cell_coverage') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cell_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (product->'projection'->'health' ? 'issues' AND (jsonb_typeof(product->'projection'->'health'->'issues') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'issues') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'formula_outcomes' AND (jsonb_typeof(product->'projection'->'health'->'formula_outcomes') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'formula_outcomes') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','outcome','error','diagnostic_ref'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('failed','not_requested','succeeded','unknown'))) OR (nested_record ? 'error' AND (jsonb_typeof(nested_record->'error') IS DISTINCT FROM 'string')) OR (nested_record ? 'diagnostic_ref' AND (jsonb_typeof(nested_record->'diagnostic_ref') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record->'diagnostic_ref') key WHERE key<>ALL(ARRAY['family','local_id','task_id','product_key','content_digest'])) OR NOT (nested_record->'diagnostic_ref' ? 'family') OR (nested_record->'diagnostic_ref' ? 'family' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'family') IS DISTINCT FROM 'string')) OR nested_record->'diagnostic_ref'->>'family' IS DISTINCT FROM 'native_metadata' OR NOT (nested_record->'diagnostic_ref' ? 'local_id') OR (nested_record->'diagnostic_ref' ? 'local_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'local_id') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'task_id') OR (nested_record->'diagnostic_ref' ? 'task_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'task_id') IS DISTINCT FROM 'number' OR nested_record->'diagnostic_ref'->>'task_id' !~ '^[0-9]+$')) OR (nested_record->'diagnostic_ref' ? 'task_id' AND (nested_record->'diagnostic_ref'->>'task_id')::numeric < 1) OR NOT (nested_record->'diagnostic_ref' ? 'product_key') OR (nested_record->'diagnostic_ref' ? 'product_key' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'product_key') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'content_digest') OR (nested_record->'diagnostic_ref' ? 'content_digest' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'content_digest') IS DISTINCT FROM 'string')) OR (nested_record->'diagnostic_ref' ? 'content_digest' AND nested_record->'diagnostic_ref'->>'content_digest' !~ '^[0-9a-f]{64}$')))))))) OR (product->'projection'->'health' ? 'candidate_policy' AND (jsonb_typeof(product->'projection'->'health'->'candidate_policy') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'candidate_policy' NOT IN ('native-font-token-vector-ocr-word-v3','native-font-token-vector-v2','native-math-font-or-token-v1'))) OR (product->'projection'->'health' ? 'cells_policy' AND (jsonb_typeof(product->'projection'->'health'->'cells_policy') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cells_policy' NOT IN ('all-nonempty-selected-cells-v1'))) OR (product->'projection'->'health' ? 'inline_scope' AND (jsonb_typeof(product->'projection'->'health'->'inline_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'inline_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'inline_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'health'->'inline_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection'->'health' ? 'cell_scope' AND (jsonb_typeof(product->'projection'->'health'->'cell_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(product->'projection'->'health'->'cell_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (product->'projection'->'health' ? 'cell_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(product->'projection'->'health'->'cell_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (product->'projection'->'health' ? 'inline_membership' AND (jsonb_typeof(product->'projection'->'health'->'inline_membership') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'inline_membership' NOT IN ('descendants','direct'))) OR (product->'projection'->'health' ? 'cell_membership' AND (jsonb_typeof(product->'projection'->'health'->'cell_membership') IS DISTINCT FROM 'string' OR product->'projection'->'health'->>'cell_membership' NOT IN ('descendants','direct'))))))))) OR (product ? 'replaces_source_view_id' AND (jsonb_typeof(product->'replaces_source_view_id') IS DISTINCT FROM 'number' OR product->>'replaces_source_view_id' !~ '^[0-9]+$')) OR (product ? 'replaces_source_view_id' AND (product->>'replaces_source_view_id')::numeric < 1) OR NOT (product ? 'analysis_eligible') OR (product ? 'analysis_eligible' AND (jsonb_typeof(product->'analysis_eligible') IS DISTINCT FROM 'boolean')) THEN RAISE EXCEPTION 'parsing record shape differs: PdfSourceViewPublication' USING ERRCODE='23514'; END IF;

 projection:=product->'projection';
 IF product->>'recipe_digest' IS DISTINCT FROM encode(sha256(p_recipe),'hex') OR
 product->>'projection_digest' IS DISTINCT FROM encode(sha256(convert_to(data.canonical_json(projection),'UTF8')),'hex') THEN
 RAISE EXCEPTION 'source view recipe/projection identity differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT native FROM ops.pdf_selected_product WHERE task_id=(product->>'native_task_id')::bigint AND product_key=product->>'native_product_key' AND content_digest=product->>'native_content_digest';
 IF EXISTS(SELECT FROM ops.pdf_published_revision WHERE task_id=native.task_id AND product_key=native.product_key AND logical_digest=native.content_digest) THEN native.health:=ops.pdf_record_scope_health(native.task_id,native.product_key,native.content_digest,ARRAY(SELECT jsonb_array_elements_text(projection->'items'))); END IF;
 -- Cross-release reuse is explicitly pinned to an archived native schema and producer contract.
 IF NOT EXISTS(SELECT FROM kb.document d JOIN ops.source_build b ON b.artifact_digest=d.content_hash JOIN ops.task t ON t.id=b.task_id JOIN ops.run r ON r.id=t.run_id
 WHERE d.id=(product->>'document_id')::bigint AND d.project_id=run.project_id AND b.task_id=native.task_id AND r.project_id=run.project_id AND EXISTS(SELECT FROM ops.source_build own WHERE own.task_id=p_task AND own.artifact_digest=b.artifact_digest)) THEN
 RAISE EXCEPTION 'native source view outside original/project custody' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT FROM sem.input WHERE release_id=native.release_id AND input_kind='dependency' AND input_name='execution/schema/pdf_products' AND encode(sha256(content),'hex')=native.contract_digest)
 OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/implementation/pdf/docling-validation.schema.json' AND encode(sha256(content),'hex')=native.schema_digest) THEN
 RAISE EXCEPTION 'native producer/consumer schema compatibility is unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT section FROM ops.pdf_published_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=product->>'section_pointer';
 IF section.label NOT IN ('section','chapter') THEN RAISE EXCEPTION 'source view requires admitted section container' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements_text(projection->'items') ptr WHERE NOT EXISTS(SELECT FROM ops.pdf_published_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=ptr))
 OR EXISTS(SELECT FROM jsonb_array_elements_text(COALESCE(projection->'ancestors','[]')) ptr WHERE NOT EXISTS(SELECT FROM ops.pdf_published_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=ptr)) THEN
 RAISE EXCEPTION 'source view references an unqualified occurrence' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements_text(projection->'items'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements_text(projection->'items')) THEN
 RAISE EXCEPTION 'source view repeats an occurrence' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(pointer ORDER BY ordinal),'[]'::jsonb) INTO expected FROM ops.pdf_published_item
 WHERE task_id=native.task_id AND product_key=native.product_key AND pointer IN (SELECT ops.native_scope_items(native.task_id,native.product_key,section.pointer,product->>'membership'));
 IF projection->'items' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'source view membership/order is incomplete or differs' USING ERRCODE='23514'; END IF;
 WITH RECURSIVE ancestry AS (
 SELECT p.*,0 depth FROM ops.pdf_published_item p WHERE p.task_id=native.task_id AND p.product_key=native.product_key AND p.pointer=section.parent_pointer
 UNION ALL SELECT p.*,a.depth+1 FROM ops.pdf_published_item p JOIN ancestry a ON p.pointer=a.parent_pointer WHERE p.task_id=native.task_id AND p.product_key=native.product_key
 ) SELECT COALESCE(jsonb_agg(pointer ORDER BY depth DESC),'[]'::jsonb) INTO expected FROM ancestry WHERE pointer NOT IN ('#/body','#/furniture');
 IF COALESCE(projection->'ancestors','[]') IS DISTINCT FROM expected THEN RAISE EXCEPTION 'source view ancestry differs' USING ERRCODE='23514'; END IF;
 FOR piece IN SELECT value FROM jsonb_array_elements(projection->'pieces') LOOP
  stop:=(piece->>'end')::bigint;
  IF (piece->>'start')::bigint<>pos OR stop<=pos OR stop>char_length(projection->>'text') THEN
   RAISE EXCEPTION 'source view pieces do not partition text' USING ERRCODE='23514'; END IF;
  spelling:=substr(projection->>'text',(pos+1)::integer,(stop-pos)::integer);
  IF piece->>'kind'='synthetic_separator' THEN
   IF piece->>'item_ref' IS NOT NULL OR spelling<>E'\n' THEN RAISE EXCEPTION 'unqualified synthetic source text' USING ERRCODE='23514'; END IF;
  ELSIF piece->>'kind'='native_text' THEN
   piece_pointer:=piece->>'item_ref';
   IF NOT (projection->'items' ? piece_pointer) THEN RAISE EXCEPTION 'piece outside selected source occurrences' USING ERRCODE='23514'; END IF;
   SELECT native_json INTO STRICT node FROM ops.pdf_published_item WHERE task_id=native.task_id AND product_key=native.product_key AND pointer=piece_pointer;
   IF piece->>'source_field'='cell_text' THEN
    node:=node->'data'->'table_cells'->((piece->>'cell_index')::integer);
   ELSIF piece->>'source_field'='chart_cell_text' THEN
    IF node->>'label'<>'picture' OR NOT piece ? 'cell_index' THEN RAISE EXCEPTION 'chart cell requires picture/cell index' USING ERRCODE='23514'; END IF;
    node:=node->'meta'->'tabular_chart'->'chart_data'->'table_cells'->((piece->>'cell_index')::integer);
   ELSIF piece->>'source_field'='chart_title' THEN
    IF node->>'label'<>'picture' OR piece ? 'cell_index' THEN RAISE EXCEPTION 'chart title requires exact picture witness' USING ERRCODE='23514'; END IF;
    node:=jsonb_build_object('text',node->'meta'->'tabular_chart'->'title');
   END IF;
   IF spelling IS DISTINCT FROM (node->>(CASE WHEN piece->>'source_field' IN ('cell_text','chart_cell_text','chart_title') THEN 'text' ELSE COALESCE(piece->>'source_field','text') END)) OR COALESCE(piece->>'source_field','text') NOT IN ('text','orig','cell_text','chart_title','chart_cell_text') THEN
    RAISE EXCEPTION 'projected source text differs from native occurrence' USING ERRCODE='23514'; END IF;
  ELSE RAISE EXCEPTION 'unadmitted source projection operation' USING ERRCODE='23514'; END IF;
  pos:=stop;
 END LOOP;
 SELECT (native.health - 'formula_outcomes') || jsonb_build_object('formula_outcomes',COALESCE(jsonb_agg(o.value ORDER BY o.n) FILTER(WHERE projection->'items' ? (o.value->>'pointer')),'[]')) INTO expected FROM jsonb_array_elements(COALESCE(native.health->'formula_outcomes','[]')) WITH ORDINALITY o(value,n);
 IF EXISTS(SELECT FROM ops.pdf_published_coverage WHERE task_id=native.task_id AND product_key=native.product_key) THEN
  expected:=expected-ARRAY['inline_scope','cell_scope','inline_membership','cell_membership','candidate_policy','cells_policy'];
  FOREACH coverage_universe IN ARRAY ARRAY['display','inline','cell'] LOOP
   SELECT * INTO coverage_row FROM ops.pdf_published_coverage c WHERE c.task_id=native.task_id AND c.product_key=native.product_key AND c.universe=coverage_universe AND
    ((c.section_pointer=section.pointer AND c.membership=product->>'membership') OR (c.outcome='complete' AND c.membership='descendants' AND (c.section_pointer=section.pointer OR projection->'ancestors' ? c.section_pointer)))
    ORDER BY (c.section_pointer=section.pointer AND c.membership=product->>'membership') DESC,c.section_pointer LIMIT 1;
   IF FOUND THEN
    expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],to_jsonb(coverage_row.outcome));
    IF coverage_universe<>'display' THEN
     expected:=jsonb_set(expected,ARRAY[coverage_universe||'_scope'],jsonb_build_array(section.pointer));
     expected:=jsonb_set(expected,ARRAY[coverage_universe||'_membership'],to_jsonb(product->>'membership'));
     expected:=jsonb_set(expected,ARRAY[CASE coverage_universe WHEN 'inline' THEN 'candidate_policy' ELSE 'cells_policy' END],to_jsonb(coverage_row.policy));
    END IF;
   ELSE expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],'"unknown"'::jsonb); END IF;
  END LOOP;
 ELSE
 SELECT CASE WHEN count(i.pointer)=0 OR bool_and(COALESCE(o.value->>'outcome'='succeeded',false)) THEN 'complete' WHEN count(o.value)>0 THEN 'partial' ELSE 'unknown' END INTO local_coverage
 FROM ops.pdf_published_item i LEFT JOIN ops.pdf_published_item parent ON parent.task_id=i.task_id AND parent.product_key=i.product_key AND parent.pointer=i.parent_pointer
 LEFT JOIN jsonb_array_elements(COALESCE(native.health->'formula_outcomes','[]')) o(value) ON o.value->>'pointer'=i.pointer
 WHERE i.task_id=native.task_id AND i.product_key=native.product_key AND projection->'items' ? i.pointer AND i.label='formula' AND COALESCE(parent.label,'') NOT IN ('table','inline');
 expected:=jsonb_set(expected,'{display_coverage}',to_jsonb(local_coverage));
 FOREACH coverage_universe IN ARRAY ARRAY['inline','cell'] LOOP
  IF native.health->>(coverage_universe||'_coverage') IN ('complete','partial') AND NOT COALESCE((
   ((native.health->(coverage_universe||'_scope') ? section.pointer) AND native.health->>(coverage_universe||'_membership')=product->>'membership') OR
   (native.health->>(coverage_universe||'_membership')='descendants' AND ((native.health->(coverage_universe||'_scope') ? section.pointer) OR EXISTS(SELECT FROM jsonb_array_elements_text(COALESCE(projection->'ancestors','[]')) parent WHERE native.health->(coverage_universe||'_scope') ? parent)))),false) THEN
   expected:=jsonb_set(expected,ARRAY[coverage_universe||'_coverage'],'"unknown"'::jsonb);
  END IF;
 END LOOP;
 END IF;
 IF pos<>char_length(projection->>'text') OR projection->'health' IS DISTINCT FROM expected THEN
 RAISE EXCEPTION 'source view text extent/health differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM kb.source_view WHERE key=product->>'key' AND release_id=run.release_id;
 IF FOUND THEN
  IF previous.projection IS DISTINCT FROM projection OR previous.native_content_digest<>native.content_digest OR previous.recipe_digest<>product->>'recipe_digest' OR previous.analysis_eligible IS DISTINCT FROM (product->>'analysis_eligible')::boolean THEN
   RAISE EXCEPTION 'immutable source view replay differs' USING ERRCODE='23514'; END IF;
  result:=previous.id;
 ELSE
  IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN RAISE EXCEPTION 'source view run is no longer writable' USING ERRCODE='P0004'; END IF;
  INSERT INTO kb.source_artifact(artifact_digest,content) VALUES(encode(sha256(p_recipe),'hex'),p_recipe) ON CONFLICT DO NOTHING;
  INSERT INTO kb.source_view(analysis_eligible,key,document_id,release_id,native_task_id,native_product_key,native_content_digest,section_pointer,membership,projection_digest,recipe_digest,projection)
  VALUES((product->>'analysis_eligible')::boolean,product->>'key',(product->>'document_id')::bigint,run.release_id,native.task_id,native.product_key,native.content_digest,section.pointer,product->>'membership',product->>'projection_digest',product->>'recipe_digest',projection) RETURNING id INTO result;
 END IF;
 IF product->>'replaces_source_view_id' IS NOT NULL AND NOT EXISTS(SELECT FROM ops.run_source_view rs JOIN kb.source_view old ON old.id=rs.source_view_id WHERE rs.run_id=p_run AND old.id=(product->>'replaces_source_view_id')::bigint AND old.document_id=(product->>'document_id')::bigint AND old.section_pointer=section.pointer AND old.membership=product->>'membership') THEN
 RAISE EXCEPTION 'source view replacement differs from selected original/section' USING ERRCODE='23514'; END IF;
 IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN
  IF NOT EXISTS(SELECT FROM ops.run_source_view WHERE run_id=p_run AND source_view_id=result AND position=p_position AND supersedes_source_view_id IS NOT DISTINCT FROM (product->>'replaces_source_view_id')::bigint) THEN
   RAISE EXCEPTION 'terminal source view replay cannot change selection' USING ERRCODE='P0004'; END IF;
  RETURN result;
 END IF;
 INSERT INTO ops.run_source_view(run_id,source_view_id,position,supersedes_source_view_id) VALUES(p_run,result,p_position,(product->>'replaces_source_view_id')::bigint) ON CONFLICT DO NOTHING;
 RETURN result;
END $view$

